#!/bin/bash
# Simple system menu

while true; do
  clear
  echo "===== MENU ====="
  echo "1) Show current date and time"
  echo "2) List files in current directory"
  echo "3) Show disk usage"
  echo "4) Show your username"
  echo "5) Quit"
  read -p "Choice: " choice
  case $choice in
    1) date ;;
    2) ls -la ;;
    3) du -sh . ;;
    4) whoami ;;
    5) echo "Goodbye!"; exit ;;
    *) echo "Invalid option"; sleep 1 ;;
  esac
  echo ""
  read -p "Press Enter to continue..."
done
